import { writeFileSync } from "node:fs";
import { sessions } from "../src/data";
import { poseIntervals, poseKeyframes } from "../src/lib/timeline";
const rules = [
  "/* Generated by npm run compile:timelines. Do not edit by hand. */",
];
for (const session of sessions)
  for (const scene of session.scenes)
    for (const actor of scene.actors)
      poseIntervals(actor, scene.durationMs).forEach((pose, index) =>
        rules.push(
          poseKeyframes(
            `pose-${session.id}-${scene.id}-${actor.id}-${index}`,
            pose.startMs,
            pose.endMs,
            scene.durationMs,
            pose.final,
          ),
        ),
      );
writeFileSync("src/app/scene-poses.css", rules.join("\n") + "\n");
